-- GZQO v1.0.0 — GENERATED by TrialBox criteria-compiler from Criterion IR (SPEC §6.3).
-- Deterministic template output; never edited by hand or produced by an LLM.
-- Parameters: $1 index_dates DATE[] ; $2 pids VARCHAR[] (NULL = all patients alive at index).
-- Output: one row per (pid, index_date) with "C_<ID>" BOOLEAN/NULL and "E_<ID>" VARCHAR per criterion.
-- Safety rules: D-275 (units, sex, order dates).
WITH
params AS (SELECT CAST($1 AS DATE[]) AS idx_dates, CAST($2 AS VARCHAR[]) AS pids),
idx AS (SELECT unnest(idx_dates) AS index_date FROM params),
base AS (
  SELECT p.pid, p.birth_date, p.sex, i.index_date FROM patient p CROSS JOIN idx i
  WHERE ((SELECT pids FROM params) IS NULL OR list_contains((SELECT pids FROM params), p.pid))
    AND (p.deceased_date IS NULL OR p.deceased_date > i.index_date)
    AND (p.deceased_date IS NOT NULL OR p.deceased IS NOT TRUE)
    AND (p.birth_date IS NULL OR p.birth_date <= i.index_date)),
vs(vs_id, system, code) AS (VALUES
  ('VS_ALT', 'http://loinc.org', '1742-6')),
a_gzqo_exc_13_1 AS (
  SELECT d.pid, d.index_date, CASE WHEN (u.n IS NULL OR (d.v AND u.not_true = 0) OR (NOT d.v AND u.not_false = 0)) THEN d.v END AS v,
         CASE WHEN (u.n IS NULL OR (d.v AND u.not_true = 0) OR (NOT d.v AND u.not_false = 0)) OR d.v IS NULL THEN d.ev ELSE u.ev END AS ev
  FROM (SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num > (o.ref_bound * 3)) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num <= (o.ref_bound * 3) THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num > (o.ref_bound * 3) THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || coalesce(strftime(o.effective, '%Y-%m-%d'), '') AS ev
    FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
          FROM (SELECT b.pid, b.index_date, o.oid, o.effective, d.detail.value_num AS value_num, o.value_cmp, o.value_code,
         FALSE AS unit_bad, o.effective IS NULL AS undated, d.detail.ref_bound AS ref_bound
  FROM base b JOIN observation o ON o.pid = b.pid
   AND (o.effective::DATE BETWEEN (b.index_date + -180) AND b.index_date OR o.effective IS NULL)
  LEFT JOIN LATERAL (SELECT (SELECT struct_pack(value_num := m.value_as_number, ref_bound := m.range_high)
FROM measurement m JOIN tb_record r ON r.record_id = m.measurement_id
AND r.cdm_table = 'measurement' JOIN tb_id_map p ON p.id_kind = 'person'
AND p.omop_id = m.person_id WHERE p.source_id = o.pid AND (CASE WHEN r.part = 0 THEN r.source_record_id ELSE r.source_record_id || '.' || m.measurement_source_value END) = o.oid
AND r.status IN ('coded', 'confirmed', 'signed', 'derived')) AS detail) d ON TRUE
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ALT' AND vs.system = o.system AND vs.code = o.code)) WHERE NOT undated) o WHERE rn = 1) d
  LEFT JOIN (SELECT pid, index_date, count(*) AS n,
         count(*) FILTER (WHERE (CASE WHEN o.value_cmp IS NULL THEN (o.value_num > (o.ref_bound * 3)) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num <= (o.ref_bound * 3) THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num > (o.ref_bound * 3) THEN TRUE END) END) IS NOT TRUE) AS not_true,
         count(*) FILTER (WHERE (CASE WHEN o.value_cmp IS NULL THEN (o.value_num > (o.ref_bound * 3)) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num <= (o.ref_bound * 3) THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num > (o.ref_bound * 3) THEN TRUE END) END) IS NOT FALSE) AS not_false, string_agg(CASE WHEN o.undated THEN o.oid || '|' || coalesce(strftime(o.effective, '%Y-%m-%d'), '') END, ';' ORDER BY o.oid) AS ev
    FROM (SELECT b.pid, b.index_date, o.oid, o.effective, d.detail.value_num AS value_num, o.value_cmp, o.value_code,
         FALSE AS unit_bad, o.effective IS NULL AS undated, d.detail.ref_bound AS ref_bound
  FROM base b JOIN observation o ON o.pid = b.pid
   AND (o.effective::DATE BETWEEN (b.index_date + -180) AND b.index_date OR o.effective IS NULL)
  LEFT JOIN LATERAL (SELECT (SELECT struct_pack(value_num := m.value_as_number, ref_bound := m.range_high)
FROM measurement m JOIN tb_record r ON r.record_id = m.measurement_id
AND r.cdm_table = 'measurement' JOIN tb_id_map p ON p.id_kind = 'person'
AND p.omop_id = m.person_id WHERE p.source_id = o.pid AND (CASE WHEN r.part = 0 THEN r.source_record_id ELSE r.source_record_id || '.' || m.measurement_source_value END) = o.oid
AND r.status IN ('coded', 'confirmed', 'signed', 'derived')) AS detail) d ON TRUE
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ALT' AND vs.system = o.system AND vs.code = o.code)) o WHERE o.undated GROUP BY pid, index_date) u
    ON u.pid = d.pid AND u.index_date = d.index_date),
-- GZQO-EXC-13 (exclusion): ALT greater than three times the row reference upper limit in the preceding 180 days.
c_gzqo_exc_13 AS (
  SELECT b.pid, b.index_date, a_gzqo_exc_13_1.v AS v,
         concat_ws(';', a_gzqo_exc_13_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_13_1 ON a_gzqo_exc_13_1.pid = b.pid AND a_gzqo_exc_13_1.index_date = b.index_date)
SELECT b.pid, b.index_date,
  c_gzqo_exc_13.v AS "C_GZQO-EXC-13", c_gzqo_exc_13.ev AS "E_GZQO-EXC-13"
FROM base b
LEFT JOIN c_gzqo_exc_13 ON c_gzqo_exc_13.pid = b.pid AND c_gzqo_exc_13.index_date = b.index_date
ORDER BY b.pid, b.index_date
